from pathlib import Path
from datetime import datetime
from itertools import combinations
import csv

import yaml
import numpy as np
import cv2
from skimage.metrics import structural_similarity as ssim

import matplotlib
matplotlib.use("Agg")  # headless backend (saves to file)
import matplotlib.pyplot as plt

# ============================================================
# SETTINGS
# ============================================================

# Path to the YOLO dataset (generated by prepare_yolo_dataset.py)
DATA_YAML = Path(
    "dataset_yolo/data.yaml"
)

# Folder where results will be saved
PROJECT_DIR = Path(
    "runs_ssim"
)

# ------------------------------------------------------------
# IMAGE STANDARDIZATION
# ------------------------------------------------------------
# SSIM requires both images to have the same size and, since
# the dataset has images of varying sizes, all of them are
# resized to a fixed size in grayscale.
# This choice affects the result (see discussion in the thesis):
# images with different aspect ratios suffer distortion on resize.

IMG_SIZE = (256, 256)   # (width, height) used in the comparison
USE_GRAYSCALE = True    # classic SSIM in grayscale

# How many pairs to show in the printed ranking / markdown
TOP_N = 50


# ============================================================
# READING THE TRAINING SPLIT IMAGES
# ============================================================

def load_train_list():
    """Reads data.yaml and lists the training split images."""

    with open(DATA_YAML, "r", encoding="utf-8") as f:
        cfg = yaml.safe_load(f)

    base = Path(cfg["path"])
    train_dir = base / cfg["train"]

    extensions = {
        ".jpg", ".jpeg", ".png",
        ".bmp", ".tif", ".tiff",
    }

    images = sorted(
        img
        for img in train_dir.iterdir()
        if img.is_file()
        and img.suffix.lower() in extensions
    )

    if not images:
        raise FileNotFoundError(
            f"No training image found in: {train_dir}"
        )

    return images


def preprocess(path):
    """Reads, converts to grayscale and resizes an image."""

    image = cv2.imread(str(path), cv2.IMREAD_COLOR)

    if image is None:
        raise ValueError(f"Failed to read image: {path}")

    if USE_GRAYSCALE:
        image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)

    image = cv2.resize(
        image,
        IMG_SIZE,
        interpolation=cv2.INTER_AREA,
    )

    return image


# ============================================================
# SSIM COMPARISON (all pairs)
# ============================================================

def compare_all(images):
    """
    Preprocesses each image once and computes SSIM for all possible pairs (N*(N-1)/2 comparisons)

    Returns the list of pairs with their scores
    """

    print(f"Preprocessing {len(images)} images...")

    names = [img.name for img in images]
    data = [preprocess(img) for img in images]

    n = len(data)
    total_pairs = n * (n - 1) // 2

    print(f"Comparing {total_pairs} pairs via SSIM...")

    results = []
    done = 0

    for i, j in combinations(range(n), 2):

        score = ssim(data[i], data[j])

        results.append(
            {
                "image_a": names[i],
                "image_b": names[j],
                "ssim": round(float(score), 4),
            }
        )

        done += 1
        if done % 5000 == 0:
            print(f"  {done}/{total_pairs} pairs...")

    # Sort from most similar to least similar
    results.sort(key=lambda r: r["ssim"], reverse=True)

    return results


# ============================================================
# OUTPUTS (CSV + MARKDOWN)
# ============================================================

def save_csv(results, csv_path):

    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(
            f,
            fieldnames=["image_a", "image_b", "ssim"],
        )
        writer.writeheader()
        writer.writerows(results)


def save_markdown(results, md_path, top_n):

    lines = []
    lines.append("# Similarity Ranking (SSIM) - training images")
    lines.append("")
    lines.append(
        f"Grayscale comparison, resized to "
        f"{IMG_SIZE[0]}x{IMG_SIZE[1]}."
    )
    lines.append("")
    lines.append(f"## Top {top_n} most similar pairs")
    lines.append("")
    lines.append("| # | Image A | Image B | SSIM |")
    lines.append("|---|---|---|---|")

    for pos, r in enumerate(results[:top_n], start=1):
        lines.append(
            f"| {pos} | {r['image_a']} | "
            f"{r['image_b']} | {r['ssim']:.4f} |"
        )

    md_path.write_text("\n".join(lines) + "\n", encoding="utf-8")


# ============================================================
# CHARTS
# ============================================================

def generate_charts(results, out_dir, top_n):

    scores = [r["ssim"] for r in results]

    # --------------------------------------------------------
    # 1) Distribution (histogram) of SSIM scores
    # --------------------------------------------------------

    fig, ax = plt.subplots(figsize=(10, 6))

    ax.hist(scores, bins=50, color="#4C72B0", edgecolor="black")
    ax.set_title(
        "Distribution of SSIM scores between pairs",
        fontsize=14,
        fontweight="bold",
    )
    ax.set_xlabel("SSIM")
    ax.set_ylabel("Number of pairs")
    ax.grid(axis="y", linestyle="--", alpha=0.4)

    fig.tight_layout()
    path_hist = out_dir / "distribuicao_ssim.png"
    fig.savefig(path_hist, dpi=150)
    plt.close(fig)

    # --------------------------------------------------------
    # 2) Horizontal bars with the top-N most similar pairs
    # --------------------------------------------------------

    top = results[:top_n]

    labels = [
        f"{r['image_a']}\n{r['image_b']}"
        for r in top
    ]
    values = [r["ssim"] for r in top]

    height = max(6, len(top) * 0.35)
    fig, ax = plt.subplots(figsize=(10, height))

    positions = range(len(top))
    ax.barh(list(positions), values, color="#55A868")

    ax.set_yticks(list(positions))
    ax.set_yticklabels(labels, fontsize=7)
    ax.invert_yaxis()  # most similar on top
    ax.set_xlabel("SSIM")
    ax.set_xlim(0, 1)
    ax.set_title(
        f"Top {top_n} most similar pairs (SSIM)",
        fontsize=14,
        fontweight="bold",
    )
    ax.grid(axis="x", linestyle="--", alpha=0.4)

    fig.tight_layout()
    path_top = out_dir / "top_pares_ssim.png"
    fig.savefig(path_top, dpi=150)
    plt.close(fig)

    return [path_hist, path_top]


# ============================================================
# EXECUTION
# ============================================================

def main():

    if not DATA_YAML.exists():
        raise FileNotFoundError(
            f"data.yaml not found: {DATA_YAML}\n"
            "Run prepare_yolo_dataset.py first."
        )

    PROJECT_DIR.mkdir(parents=True, exist_ok=True)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    out_dir = PROJECT_DIR / f"ssim_{timestamp}"
    out_dir.mkdir(parents=True, exist_ok=True)

    images = load_train_list()

    results = compare_all(images)

    top_n = min(TOP_N, len(results))

    # --------------------------------------------------------
    # RANKING IN THE TERMINAL
    # --------------------------------------------------------

    print("\n" + "=" * 70)
    print(f"SIMILARITY RANKING (top {top_n} pairs)")
    print("=" * 70)

    print(f"{'#':>3}  {'SSIM':>7}  Pair")
    print("-" * 70)

    for pos, r in enumerate(results[:top_n], start=1):
        print(
            f"{pos:>3}  {r['ssim']:>7.4f}  "
            f"{r['image_a']} <-> {r['image_b']}"
        )

    # --------------------------------------------------------
    # SAVE OUTPUTS
    # --------------------------------------------------------

    csv_path = out_dir / "ssim_pares.csv"
    md_path = out_dir / "ssim_ranking.md"

    save_csv(results, csv_path)
    save_markdown(results, md_path, top_n)

    charts = generate_charts(results, out_dir, top_n)

    # --------------------------------------------------------
    # STATISTICAL SUMMARY
    # --------------------------------------------------------

    scores = np.array([r["ssim"] for r in results])

    print("\n" + "=" * 70)
    print("SUMMARY")
    print("=" * 70)
    print(f"Images compared: {len(images)}")
    print(f"Pairs evaluated: {len(results)}")
    print(f"Mean SSIM:       {scores.mean():.4f}")
    print(f"Median SSIM:     {np.median(scores):.4f}")
    print(f"Max SSIM:        {scores.max():.4f}")
    print(f"Min SSIM:        {scores.min():.4f}")

    print("\n" + "=" * 70)
    print("GENERATED FILES")
    print("=" * 70)
    print(f"CSV (all pairs):    {csv_path}")
    print(f"Markdown (top {top_n}): {md_path}")
    for c in charts:
        print(f"Chart:              {c}")
    print("=" * 70)


if __name__ == "__main__":
    main()
